import { useEffect, useMemo } from 'react'
import { actionContextIdentity } from '../../../../data/action_context'
import {
    actionRunSettingsService,
} from '../../../../services/actions/action_run_settings_service'
import { AgentAction } from './agent_action'
import { ActionPopupFrame } from './action_popup_frame'
import { CommandAction } from './command_action'
import { createActionPopupBindings, worktreeValidationMessage } from './action_popup_runtime'
import type { ActionPopupContentProps, ActionPopupRuntime } from './action_popup_types'

export { CARD_RUN_POPUP_SIZE_STORAGE_KEY, PROJECT_AGENT_POPUP_SIZE_STORAGE_KEY } from './action_popup_frame'

/** Selects the action-specific popup content while preserving its runtime for the selected action. */
export function ActionPopupContent(props: ActionPopupContentProps) {
    const { action, assignmentContext, initialRunId } = props
    const settingsContextIdentity = actionContextIdentity(assignmentContext)
    const settingsStore = useMemo(
        () => assignmentContext.cardInternalId
            ? actionRunSettingsService.getCardStore(assignmentContext.cardInternalId, action.id)
            : actionRunSettingsService.getSessionStore(action.id, settingsContextIdentity),
        [action.id, assignmentContext.cardInternalId, settingsContextIdentity],
    )
    const bindings = useMemo(
        () => createActionPopupBindings(action, assignmentContext, initialRunId),
        [action, assignmentContext, initialRunId],
    )
    useEffect(() => {
        bindings.usageValuesService.start()

        return () => {
            bindings.usageValuesService.stop()
            bindings.bindingStore.dispose()
        }
    }, [bindings])
    const runtime: ActionPopupRuntime = {
        ...bindings,
        runValidationError: worktreeValidationMessage(action, assignmentContext),
        settingsStore,
    }

    return (
        <ActionPopupFrame
            bindingStore={bindings.bindingStore}
            contentProps={props}
            conversationStore={bindings.conversationStore}
        >
            {action.type === 'agent'
                ? (
                    <AgentAction
                        action={action}
                        assignmentContext={assignmentContext}
                        baseContext={props.baseContext}
                        popupEntryId={props.popupEntryId}
                        readOnlyMessage={props.readOnlyMessage}
                        runtime={runtime}
                    />
                ) : (
                    <CommandAction
                        action={action}
                        assignmentContext={assignmentContext}
                        baseContext={props.baseContext}
                        readOnlyMessage={props.readOnlyMessage}
                        runtime={runtime}
                    />
                )}
        </ActionPopupFrame>
    )
}

import { Stack, Typography } from '@mui/material'
import type { ActionContext } from '../../../../data/action_context'
import type { ActionDefinition } from '../../../../data/action_types'
import { useBoundRunId, useRunSelector } from '../../../hooks/use_action_runs'
import { ActionScheduleOwner } from '../schedule/action_schedule_owner'
import { ActionRunHistoryOwner } from '../state/action_run_history_owner'
import { ActionRunStatusOwner } from '../state/action_run_status_owner'
import { ActionAgentInteraction } from './action_agent_interaction'
import { ActionPopupBottomRow } from './action_popup_bottom_row'
import type { ActionPopupRuntime } from './action_popup_types'
import { ActionRunDisabledMessage } from './action_run_disabled_message'

interface CommandActionProps {
    action: ActionDefinition
    assignmentContext: ActionContext
    baseContext: ActionContext
    readOnlyMessage: string | null
    runtime: ActionPopupRuntime
}

/** Command status, history, scheduling, and run controls. */
export function CommandAction(props: CommandActionProps) {
    const { action, assignmentContext, baseContext, readOnlyMessage, runtime } = props
    const {
        bindingStore, conversationStore, historyStore, inputStore, resultStore, runValidationError, scheduleStore,
        settingsStore,
    } = runtime
    const boundRunId = useBoundRunId(bindingStore)
    const activeActionType = useRunSelector(boundRunId, (run) => run?.activeActionType ?? null)
    const showBottomRow = activeActionType !== 'agent'

    if (readOnlyMessage) {
        return (
            <Stack data-testid="action-popup-scroll-body" spacing={2} sx={{ flex: 1, minHeight: 0, overflow: 'auto', px: 1.5, py: 1 }}>
                <Typography color="text.secondary" role="note" variant="caption">{readOnlyMessage}</Typography>
            </Stack>
        )
    }

    return (
        <>
            <Stack data-testid="action-popup-scroll-body" spacing={2} sx={{ flex: 1, minHeight: 0, overflow: 'auto', px: 1.5, py: 1 }}>
                <ActionAgentInteraction action={action} assignmentContext={assignmentContext} runtime={runtime} />
                <ActionScheduleOwner action={action} context={baseContext} store={scheduleStore} />
                <ActionRunStatusOwner bindingStore={bindingStore} resultStore={resultStore} />
                <ActionRunDisabledMessage action={action} settingsStore={settingsStore} />
                {runValidationError ? (
                    <Typography color="error.main" role="alert" variant="caption">
                        {runValidationError}
                    </Typography>
                ) : null}
                <ActionRunHistoryOwner store={historyStore} />
            </Stack>
            {showBottomRow ? (
                <ActionPopupBottomRow
                    action={action}
                    assignmentContext={assignmentContext}
                    bindingStore={bindingStore}
                    conversationStore={conversationStore}
                    historyStore={historyStore}
                    inputStore={inputStore}
                    settingsStore={settingsStore}
                    resultStore={resultStore}
                    runValidationError={runValidationError}
                    scheduleStore={scheduleStore}
                />
            ) : null}
        </>
    )
}
